# Phase 9 seeds the six evolution thresholds and gives every existing fish the
# goldfish species, recomputing its stage from its level. Pre-release data, so
# this one-time stage change is acceptable.
EVOLUTION_LEVELS = [1, 10, 25, 40, 55, 70]
GOLDIE_STAGES = [
    "Goldie Egg",
    "Little Goldie",
    "Bubble Goldie",
    "Royal Goldie",
    "Grand Goldie",
    "Sun Goldie",
]
STAGE_NAMES = [
    "Hatchling",
    "Young",
    "Growing",
    "Grand",
    "Shining",
    "Legendary",
]


def seed_phase9(apps, schema_editor):
    EvolutionStage = apps.get_model("game", "EvolutionStage")
    FishSpecies = apps.get_model("game", "FishSpecies")
    SpeciesStageName = apps.get_model("game", "SpeciesStageName")
    Fish = apps.get_model("game", "Fish")

    for stage_number, min_level in enumerate(EVOLUTION_LEVELS):
        EvolutionStage.objects.update_or_create(
            stage_number=stage_number,
            defaults={
                "name": STAGE_NAMES[stage_number],
                "min_level": min_level,
                "sprite_key": "",
            },
        )
    EvolutionStage.objects.filter(stage_number__gt=len(EVOLUTION_LEVELS) - 1).delete()

    goldfish, _created = FishSpecies.objects.update_or_create(
        key="goldfish",
        defaults={
            "name": "Goldfish",
            "description": "A round orange fish with a long, flowing tail.",
            "order": 1,
            "active": True,
        },
    )
    for stage_number, name in enumerate(GOLDIE_STAGES):
        SpeciesStageName.objects.update_or_create(
            species=goldfish,
            stage_number=stage_number,
            defaults={"name": name},
        )

    for fish in Fish.objects.all():
        stage = max(
            index
            for index, minimum in enumerate(EVOLUTION_LEVELS)
            if minimum <= fish.level
        )
        fish.species_id = goldfish.pk
        fish.stage = stage
        fish.save(update_fields=["species", "stage"])


